import sys
from fractions import Fraction

def main():
    import sys
    import fractions

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    N, M = readints()
    adj = [[] for _ in range(N)]
    for _ in range(M):
        K, L = readints()
        adj[K].append(L)
        adj[L].append(K)

    # Create the system of equations
    eqs = []
    for i in range(N):
        if i == N - 1:
            eqs.append([Fraction(1, 1)] + [Fraction(0, 1)] * (N - 1))
        else:
            row = [Fraction(0, 1)] * N
            row[i] = Fraction(-1, 1)
            for j in adj[i]:
                row[j] += Fraction(1, len(adj[i]))
            eqs.append(row)

    # Solve the system of equations
    def gauss_jordan_elimination(eqs):
        n = len(eqs)
        for i in range(n):
            # Find the pivot row
            max_row = i
            for j in range(i + 1, n):
                if abs(eqs[j][i]) > abs(eqs[max_row][i]):
                    max_row = j
            # Swap rows
            eqs[i], eqs[max_row] = eqs[max_row], eqs[i]
            # Normalize the pivot row
            pivot = eqs[i][i]
            for j in range(n):
                eqs[i][j] /= pivot
            # Eliminate other rows
            for j in range(n):
                if j != i:
                    factor = eqs[j][i]
                    for k in range(n):
                        eqs[j][k] -= factor * eqs[i][k]

    gauss_jordan_elimination(eqs)

    # Extract the solution
    solution = [eq[-1] for eq in eqs]
    print(f"{solution[0]:.6f}")

if __name__ == "__main__":
    main()
